const homeView = document.getElementById('home-view');
const articleView = document.getElementById('article-view');

/* Router: show full article or homepage */
function render() {
  const hash = window.location.hash || '';
  const m = hash.match(/^#article-(\d+)$/);
  const a = m && articles.find(function(x) { return x.id === Number(m[1]); });

  if (!a) {
    if (articleView) {
      articleView.hidden = true;
      articleView.innerHTML = '';
    }
    if (homeView) {
      homeView.hidden = false;
    }
    document.title = 'HELPER ONLINE — Ideas, Stories & Knowledge';
    return;
  }

  if (homeView) homeView.hidden = true;
  if (articleView) {
    articleView.hidden = false;
    document.title = a.title + ' — HELPER ONLINE';
    articleView.innerHTML =
      '<div class="wrap narrow article-head">' +
        '<a class="back" href="#blog">&larr; Back to Articles</a>' +
        '<p class="crumbs"><a href="#blog">Blog</a> <span>/</span> <a href="#blog">' + a.category + '</a></p>' +
        '<h1 class="article-title">' + a.title + '</h1>' +
        '<p class="meta">' + a.date + ' &middot; ' + a.author + '</p>' +
        '<p class="article-sub">' + a.subtitle + '</p>' +
      '</div>' +
      (a.image ? '<div class="wrap"><img class="article-hero" src="' + a.image + '" alt="' + a.title + '" width="1200" height="675" loading="eager" onerror="this.style.opacity=0.7"></div>' : '') +
      '<div class="wrap narrow article-body">' + a.content +
        '<form class="comment-form" id="comment-form">' +
          '<h2>Leave a comment</h2>' +
          '<label>Comment<textarea name="comment" rows="6" required placeholder="Write your comment here..."></textarea></label>' +
          '<label>Name<input name="name" type="text" required placeholder="Your name"></label>' +
          '<label>Email<input name="email" type="email" required placeholder="you@example.com"></label>' +
          '<label>Website<input name="website" type="url" placeholder="https://example.com (optional)"></label>' +
          '<label class="comment-check"><input name="save-info" type="checkbox"> <span>Save my name, email, and website in this browser for the next time I comment.</span></label>' +
          '<button class="btn btn-primary" type="submit">Submit Comment</button>' +
          '<p class="form-msg" id="form-msg" style="display:none;">Thank you! Your comment has been submitted.</p>' +
        '</form>' +
        '<p style="margin-top: 24px;"><a class="back" href="#blog">&larr; Back to Articles</a></p>' +
      '</div>';

    window.scrollTo({ top: 0, behavior: 'instant' });

    const commentForm = document.getElementById('comment-form');
    if (commentForm) {
      commentForm.addEventListener('submit', function (e) {
        e.preventDefault();
        this.reset();
        const msg = document.getElementById('form-msg');
        if (msg) msg.style.display = 'block';
      });
    }
  }
}

window.addEventListener('hashchange', render);
render();

/* ---- pagination system ---- */
(function () {
  const PER_PAGE = 9;
  const grid = document.querySelector('#blog .grid');
  const nav = document.getElementById('pagination');
  if (!grid || !nav) return;
  const cards = Array.prototype.slice.call(grid.children);
  const pages = Math.ceil(cards.length / PER_PAGE);
  let current = 1;

  function show(page) {
    current = Math.min(Math.max(1, page), pages);
    cards.forEach(function (card, i) {
      const on = i >= (current - 1) * PER_PAGE && i < current * PER_PAGE;
      card.style.display = on ? '' : 'none';
    });
    draw();
  }

  function pageBtn(n) {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = n;
    if (n === current) b.className = 'is-active';
    b.addEventListener('click', function () {
      show(n);
      const blogSec = document.getElementById('blog');
      if (blogSec) blogSec.scrollIntoView({ behavior: 'smooth' });
    });
    return b;
  }

  function draw() {
    nav.innerHTML = '';
    if (pages < 2) return;

    // Prev Button
    const prev = document.createElement('button');
    prev.type = 'button';
    prev.textContent = 'Prev';
    prev.disabled = current === 1;
    prev.addEventListener('click', function () {
      show(current - 1);
      const blogSec = document.getElementById('blog');
      if (blogSec) blogSec.scrollIntoView({ behavior: 'smooth' });
    });
    nav.appendChild(prev);

    // Numbered page list with ellipsis
    const list = [];
    for (let i = 1; i <= pages; i++) {
      if (i === 1 || i === pages || Math.abs(i - current) <= 1) {
        list.push(i);
      } else if (list[list.length - 1] !== '...') {
        list.push('...');
      }
    }

    list.forEach(function (item) {
      if (item === '...') {
        const d = document.createElement('span');
        d.className = 'dots';
        d.textContent = '...';
        nav.appendChild(d);
      } else {
        nav.appendChild(pageBtn(item));
      }
    });

    // Next Button
    const next = document.createElement('button');
    next.type = 'button';
    next.textContent = 'Next';
    next.disabled = current === pages;
    next.addEventListener('click', function () {
      show(current + 1);
      const blogSec = document.getElementById('blog');
      if (blogSec) blogSec.scrollIntoView({ behavior: 'smooth' });
    });
    nav.appendChild(next);
  }

  show(1);
})();
